(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-539":{scenario:{company:"Thanh Phong Coatings",supervisor:{name:"Đỗ Thị Minh Châu",role:{vi:"Trưởng phòng An toàn - Sức khỏe - Môi trường",en:"Health, Safety & Environment Manager"}},ref_code:"IH-4417",title:{vi:"Đo đúng phơi nhiễm. Chọn đúng phin lọc. Không giấu số liệu.",en:"Measure true exposure. Pick the right filter. Hide no data."},brief:{vi:"Bạn rà soát hồ sơ đánh giá phơi nhiễm IH-4417 cho công nhân phòng pha sơn dùng dung môi gốc xylene. Mẫu cá nhân ca 8 giờ: 2 giờ ở 260 mg/m3, 4 giờ ở 110 mg/m3, 2 giờ ở 38 mg/m3 (giới hạn TWA mô phỏng 100 mg/m3). Đối chiếu bản nháp với hồ sơ đã duyệt, sửa loại phin lọc hô hấp và nồng độ trung bình theo thời gian 8 giờ, rồi lập báo cáo có căn cứ.",en:"You are reviewing exposure assessment IH-4417 for paint-mixing workers using a xylene-based solvent. The 8-hour personal samples are: 2 hours at 260 mg/m3, 4 hours at 110 mg/m3 and 2 hours at 38 mg/m3 (training TWA limit 100 mg/m3). Compare the draft with the approved file, correct the respirator filter type and the 8-hour time-weighted average, then write an evidence-based report."},reference_title:{vi:"Hồ sơ đánh giá phơi nhiễm hóa chất đã duyệt · IH-4417",en:"Approved chemical exposure assessment · IH-4417"},fields:[{id:"FILTER",label:{vi:"Loại phin lọc mặt nạ cấp phát",en:"Issued respirator filter type"},initial:"P2",expected:"A2",choices:["P2","A2","B2"],reference:"Ma trận chọn phương tiện bảo vệ hô hấp",hint:{vi:"Xylene là hơi hữu cơ điểm sôi khoảng 140°C; phin lọc bụi không giữ được hơi dung môi.",en:"Xylene is an organic vapour boiling near 140°C; a particle filter cannot capture solvent vapour."}},{id:"TWA_MG",label:{vi:"Nồng độ TWA 8 giờ (mg/m3)",en:"8-hour TWA concentration (mg/m3)"},initial:"136",expected:"129.5",reference:"Phiếu kết quả lấy mẫu cá nhân",ref_value:{vi:"Ca 8 giờ: 2 giờ 260 mg/m3; 4 giờ 110 mg/m3; 2 giờ 38 mg/m3",en:"8-hour shift: 2 h at 260 mg/m3; 4 h at 110 mg/m3; 2 h at 38 mg/m3"},hint:{vi:"Không lấy trung bình cộng các mẫu; phải nhân từng nồng độ với thời gian phơi nhiễm.",en:"Do not average the samples; weight each concentration by its exposure time."}}],sop32:{vi:"TWA 8 giờ = tổng (nồng độ từng giai đoạn x số giờ phơi nhiễm) chia cho 8 giờ; so sánh với giới hạn TWA mô phỏng 100 mg/m3 để quyết định biện pháp kiểm soát.",en:"8-hour TWA = sum of (concentration of each period x exposure hours) divided by 8 hours; compare with the training TWA limit of 100 mg/m3 to decide control measures."},context:{label:"HỒ SƠ PHƠI NHIỄM / IH-4417",metrics:[{label:{vi:"Khu vực",en:"Area"},value:"Paint mixing room"},{label:{vi:"Giới hạn TWA mô phỏng",en:"Training TWA limit"},value:"100 mg/m3"},{label:{vi:"Vận tốc hút chụp hút",en:"Hood capture velocity"},value:"0.3 / 0.5 m/s"}]},terminal:{system:"ehs-monitor",settable:["FILTER","TWA_MG"],commands:[{cmd:"status",out:{vi:"Phòng pha sơn: 6 công nhân/ca, quạt hút cục bộ chạy 72% công suất, bản nháp IH-4417 đang ghi FILTER=P2, TWA_MG=136",en:"Paint mixing room: 6 workers per shift, local exhaust fan at 72% capacity, draft IH-4417 shows FILTER=P2, TWA_MG=136"}},{cmd:"cat sds_section8.txt",out:{vi:"SDS mục 8: hơi hữu cơ, điểm sôi 138-144°C; khi vượt giới hạn dùng mặt nạ phin lọc khí hữu cơ loại A; quy trình chỉ phát sinh hơi, không có sương sơn",en:"SDS section 8: organic vapour, boiling point 138-144°C; above the limit use organic gas filter type A; the process emits vapour only, no paint mist"}},{cmd:"cat sampling_log.txt",out:{vi:"Mẫu cá nhân NV-03: 07:00-09:00 260 mg/m3; 09:00-13:00 110 mg/m3; 13:00-15:00 38 mg/m3; tổng 8 giờ",en:"Personal sample NV-03: 07:00-09:00 260 mg/m3; 09:00-13:00 110 mg/m3; 13:00-15:00 38 mg/m3; total 8 hours"}},{cmd:"lev-check mixroom",out:{vi:"Chụp hút bồn pha: vận tốc đo 0.3 m/s, thiết kế 0.5 m/s; màng lọc ống gió bị bít 60%",en:"Mixing tank hood: measured 0.3 m/s, design 0.5 m/s; duct filter 60% clogged"}},{cmd:"cat ppe_issue.txt",out:{vi:"Phiếu cấp phát tuần này: 12 khẩu trang lọc bụi P2, chưa cấp phin lọc khí hữu cơ",en:"This week's issue slip: 12 P2 particle masks, no organic gas filters issued"}}]},crisis:{vi:"Giám đốc sản xuất nhắn: “Đừng đưa số 129.5 vào báo cáo, tuần sau khách hàng đến đánh giá. Lấy mẫu lúc quạt chạy tốt mà ghi, công nhân cứ đeo khẩu trang cũ là được.”",en:"The production director messages: “Keep 129.5 out of the report, the customer audit is next week. Use a sample from when the fan ran well, workers can keep the old masks.”"},options:{safe:{vi:"Ghi đúng TWA 129.5 mg/m3, cấp ngay phin A2, sửa chụp hút, giới hạn thời gian phơi nhiễm, báo trưởng phòng HSE và lấy mẫu lại sau khi khắc phục.",en:"Report the true TWA of 129.5 mg/m3, issue A2 filters now, repair the hood, limit exposure time, inform the HSE manager and resample after the fix."},shortcut:{vi:"Chọn mẫu đo lúc quạt chạy tốt để báo cáo đạt, sau đợt đánh giá mới xử lý.",en:"Report only the sample taken when the fan ran well to pass, and fix things after the audit."},wait:{vi:"Để nguyên bản nháp và chờ giám đốc sản xuất tự quyết định có báo cáo hay không.",en:"Leave the draft as is and wait for the production director to decide whether to report."}},questions:{vi:["Vì sao TWA đúng là 129.5 mg/m3 chứ không phải 136? Mức này dẫn tới biện pháp kiểm soát nào?","Theo thứ bậc kiểm soát, bạn ưu tiên biện pháp gì trước khi dựa vào phin lọc A2, và xử lý áp lực sửa số liệu ra sao?"],en:["Why is the correct TWA 129.5 mg/m3 rather than 136? Which control measures does this level trigger?","Under the hierarchy of controls, what do you prioritise before relying on A2 filters, and how do you handle the pressure to alter data?"]},hints:{vi:["Đặt bản nháp cạnh ma trận chọn phương tiện bảo vệ hô hấp và đọc lại SDS mục 8.","Áp dụng SOP mục 3.2: nhân nồng độ với thời gian của từng giai đoạn rồi chia cho 8 giờ.","Đọc lại SOP mục 4.2: số liệu quan trắc không được chọn lọc hay sửa để vượt qua đánh giá."],en:["Place the draft next to the respiratory protection matrix and re-read SDS section 8.","Apply SOP 3.2: multiply each concentration by its duration, then divide by 8 hours.","Re-read SOP 4.2: monitoring data must never be cherry-picked or altered to pass an audit."]}},learning:{summary:{vi:"Kỹ sư An toàn, Sức khỏe và Môi trường (HSE) nhà máy nhận diện mối nguy, đánh giá rủi ro, quan trắc môi trường lao động và thiết lập biện pháp kiểm soát để không ai bị thương hay mắc bệnh nghề nghiệp, đồng thời giữ nhà máy tuân thủ pháp luật môi trường. Công việc đòi hỏi hiểu quy trình công nghệ, đọc được số liệu đo, áp dụng thứ bậc kiểm soát và đủ bản lĩnh để dừng việc khi không an toàn.",en:"A plant Health, Safety and Environment (HSE) engineer identifies hazards, assesses risks, monitors the working environment and sets controls so nobody is injured or develops an occupational disease, while keeping the plant compliant with environmental law. The role requires understanding the process, reading measurement data, applying the hierarchy of controls and having the courage to stop work when it is unsafe."},responsibilities:{vi:["Nhận diện mối nguy, đánh giá rủi ro (HIRA) cho công việc thường xuyên và không thường xuyên.","Tổ chức quan trắc môi trường lao động, đánh giá phơi nhiễm hóa chất, tiếng ồn, nhiệt.","Vận hành hệ thống giấy phép làm việc: công việc nóng, không gian hạn chế, làm việc trên cao, LOTO.","Điều tra sự cố, tìm nguyên nhân gốc và theo dõi hành động khắc phục, phòng ngừa.","Quản lý tuân thủ môi trường: chất thải nguy hại, nước thải, khí thải và báo cáo định kỳ."],en:["Identify hazards and assess risks (HIRA) for routine and non-routine work.","Organise workplace monitoring and assess exposure to chemicals, noise and heat.","Run the permit-to-work system: hot work, confined space, work at height and LOTO.","Investigate incidents, find root causes and track corrective and preventive actions.","Manage environmental compliance: hazardous waste, wastewater, air emissions and periodic reports."]},competencies:[{name:{vi:"Đánh giá rủi ro",en:"Risk assessment"},desc:{vi:"Xác định mối nguy, ước lượng khả năng và hậu quả, chọn biện pháp theo thứ bậc kiểm soát.",en:"Identify hazards, estimate likelihood and severity, and choose controls by the hierarchy of controls."}},{name:{vi:"Vệ sinh công nghiệp",en:"Industrial hygiene"},desc:{vi:"Lập kế hoạch lấy mẫu, tính TWA, STEL và đánh giá hiệu quả thông gió cục bộ.",en:"Plan sampling, calculate TWA and STEL, and evaluate local exhaust ventilation performance."}},{name:{vi:"Điều tra sự cố",en:"Incident investigation"},desc:{vi:"Dùng 5 Why, sơ đồ xương cá, cây sự cố để tìm nguyên nhân gốc, không đổ lỗi cá nhân.",en:"Use 5 Whys, fishbone and fault tree to find root causes without blaming individuals."}},{name:{vi:"Tuân thủ pháp luật",en:"Legal compliance"},desc:{vi:"Cập nhật quy định an toàn lao động, môi trường và duy trì hồ sơ sẵn sàng thanh tra.",en:"Track safety and environmental regulations and keep records ready for inspection."}},{name:{vi:"Bản lĩnh và văn hóa an toàn",en:"Safety leadership"},desc:{vi:"Dám dừng công việc nguy hiểm, báo cáo trung thực và huấn luyện người lao động.",en:"Stop dangerous work, report honestly and coach workers on safe behaviour."}}],knowledge:{vi:["Luật An toàn, vệ sinh lao động số 84/2015/QH13 và các văn bản hướng dẫn.","Nghị định 44/2016/NĐ-CP về kiểm định kỹ thuật an toàn, huấn luyện an toàn và quan trắc môi trường lao động.","Luật Bảo vệ môi trường số 72/2020/QH14 và quy định về quản lý chất thải nguy hại.","ISO 45001:2018 hệ thống quản lý an toàn, sức khỏe nghề nghiệp; ISO 14001:2015 hệ thống quản lý môi trường.","Thứ bậc kiểm soát: loại bỏ, thay thế, kỹ thuật, hành chính, phương tiện bảo vệ cá nhân.","Phân loại phin lọc hô hấp: phin bụi P1-P3, phin khí A, B, E, K theo nhóm chất."],en:["Law on Occupational Safety and Health No. 84/2015/QH13 and its implementing documents.","Decree 44/2016/ND-CP on safety inspection, safety training and workplace environment monitoring.","Law on Environmental Protection No. 72/2020/QH14 and hazardous waste management rules.","ISO 45001:2018 occupational health and safety management; ISO 14001:2015 environmental management.","Hierarchy of controls: elimination, substitution, engineering, administrative, personal protective equipment.","Respirator filter classes: particle P1-P3, gas filters A, B, E, K by substance group."]},tools:["Máy lấy mẫu khí cá nhân","Máy đo khí đa chỉ tiêu","Máy đo tiếng ồn tích phân","Đồng hồ đo vận tốc gió","Phần mềm quản lý sự cố HSE"],kpis:{vi:["Tần suất tai nạn mất ngày công (LTIFR) trên một triệu giờ làm việc.","Tỷ lệ hành động khắc phục sau sự cố đóng đúng hạn.","Tỷ lệ vị trí quan trắc đạt giới hạn cho phép.","Số báo cáo cận nguy (near miss) được ghi nhận mỗi tháng."],en:["Lost time injury frequency rate (LTIFR) per million hours worked.","Share of incident corrective actions closed on time.","Share of monitored positions within permissible limits.","Number of near-miss reports logged per month."]},day:[{time:"07:30",vi:"Họp an toàn đầu ca, nhắc mối nguy của công việc đặc biệt trong ngày.",en:"Run the pre-shift safety talk and flag hazards of today's special jobs."},{time:"09:00",vi:"Kiểm tra hiện trường, phê duyệt giấy phép công việc nóng và không gian hạn chế.",en:"Walk the floor and approve hot work and confined space permits."},{time:"11:00",vi:"Lấy mẫu không khí vùng thở công nhân và đo vận tốc chụp hút.",en:"Take breathing-zone air samples and measure hood capture velocity."},{time:"14:00",vi:"Điều tra một vụ cận nguy, phỏng vấn nhân chứng và vẽ sơ đồ nguyên nhân.",en:"Investigate a near miss, interview witnesses and map the causes."},{time:"16:30",vi:"Cập nhật sổ theo dõi hành động khắc phục và báo cáo chất thải nguy hại.",en:"Update the corrective action log and the hazardous waste report."}],mistakes:{vi:["Lấy trung bình cộng các mẫu thay vì trung bình theo thời gian phơi nhiễm.","Cấp khẩu trang lọc bụi cho môi trường hơi dung môi, tạo cảm giác an toàn giả.","Chỉ dựa vào phương tiện bảo vệ cá nhân mà bỏ qua sửa chữa thông gió và thay thế hóa chất."],en:["Taking the arithmetic mean of samples instead of the time-weighted average.","Issuing particle masks for solvent vapour, which creates false confidence.","Relying only on PPE while skipping ventilation repair and chemical substitution."]},career:[{vi:"Nhân viên an toàn hiện trường",en:"Field safety officer"},{vi:"Kỹ sư HSE nhà máy",en:"Plant HSE engineer"},{vi:"Trưởng phòng HSE",en:"HSE manager"},{vi:"Giám đốc HSE khu vực hoặc tập đoàn",en:"Regional or corporate HSE director"}],glossary:[{term:"TWA",vi:"Nồng độ trung bình theo thời gian của ca làm việc 8 giờ, dùng để so sánh với giới hạn phơi nhiễm.",en:"Time-weighted average concentration over an 8-hour shift, compared with the exposure limit."},{term:"STEL",vi:"Giới hạn phơi nhiễm ngắn hạn, thường tính trung bình trong 15 phút.",en:"Short-term exposure limit, usually averaged over 15 minutes."},{term:"LEV",vi:"Hệ thống thông gió hút cục bộ, thu hơi khí độc ngay tại nguồn phát sinh.",en:"Local exhaust ventilation that captures contaminants at the source."},{term:"LOTO",vi:"Khóa và gắn thẻ cô lập năng lượng trước khi sửa chữa, bảo trì thiết bị.",en:"Lockout and tagout to isolate energy before repair or maintenance."},{term:"HIRA",vi:"Nhận diện mối nguy và đánh giá rủi ro, nền tảng để chọn biện pháp kiểm soát.",en:"Hazard identification and risk assessment, the basis for choosing controls."}],quiz:[{q:{vi:"Mẫu ca 8 giờ: 4 giờ ở 150 mg/m3 và 4 giờ ở 50 mg/m3. TWA 8 giờ bằng bao nhiêu?",en:"An 8-hour shift has 4 h at 150 mg/m3 and 4 h at 50 mg/m3. What is the 8-hour TWA?"},options:{vi:["200 mg/m3","75 mg/m3","150 mg/m3","100 mg/m3"],en:["200 mg/m3","75 mg/m3","150 mg/m3","100 mg/m3"]},answer:3,explain:{vi:"TWA = (4 x 150 + 4 x 50) / 8 = 800 / 8 = 100 mg/m3, đúng bằng giới hạn mô phỏng.",en:"TWA = (4 x 150 + 4 x 50) / 8 = 800 / 8 = 100 mg/m3, exactly at the training limit."}},{q:{vi:"Theo thứ bậc kiểm soát, biện pháp nào được ưu tiên cao nhất?",en:"Which control has the highest priority in the hierarchy of controls?"},options:{vi:["Loại bỏ mối nguy","Cấp phương tiện bảo vệ cá nhân","Huấn luyện người lao động","Dán biển cảnh báo"],en:["Eliminate the hazard","Issue personal protective equipment","Train workers","Post warning signs"]},answer:0,explain:{vi:"Loại bỏ mối nguy đứng đầu; phương tiện bảo vệ cá nhân là lớp cuối cùng.",en:"Elimination comes first; personal protective equipment is the last line of defence."}},{q:{vi:"Công nhân tiếp xúc hơi dung môi hữu cơ điểm sôi 140°C cần loại phin lọc nào?",en:"Which filter suits workers exposed to an organic solvent vapour boiling at 140°C?"},options:{vi:["Phin bụi P2","Phin khí hữu cơ loại A","Phin khí vô cơ loại B","Phin amoniac loại K"],en:["P2 particle filter","Type A organic gas filter","Type B inorganic gas filter","Type K ammonia filter"]},answer:1,explain:{vi:"Phin loại A dành cho khí, hơi hữu cơ có điểm sôi trên 65°C; phin bụi không giữ được hơi.",en:"Type A filters cover organic gases and vapours boiling above 65°C; particle filters do not stop vapour."}},{q:{vi:"Sếp yêu cầu bỏ kết quả đo vượt giới hạn khỏi báo cáo trước đợt đánh giá. Bạn làm gì?",en:"Your boss asks you to drop an over-limit result from the report before an audit. What do you do?"},options:{vi:["Làm theo vì đánh giá rất quan trọng","Đo lại đến khi có số đạt","Ghi đúng kết quả, triển khai kiểm soát và báo cáo cấp có thẩm quyền","Im lặng và không nộp báo cáo"],en:["Comply because the audit matters","Resample until a result passes","Report the true result, apply controls and escalate","Stay silent and submit nothing"]},answer:2,explain:{vi:"Che giấu số liệu phơi nhiễm đặt sức khỏe người lao động vào rủi ro và vi phạm pháp luật.",en:"Hiding exposure data puts workers' health at risk and breaks the law."}}],tools_en:["Personal air sampling pump","Multi-gas detector","Integrating sound level meter","Air velocity meter (anemometer)","HSE incident management software"]}}})})(window.KKR);
